import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";

export type DbtCloud = {
  /**
   * Unique ID of the model assigned by dbt (usually some combination of the schema and table name)
   */
  dbtUniqueId: string;
  /** Compiled SQL in the dbt model */
  compiledSql: string;
  rawSql: string;
  /** Name of the table generated by the dbt model */
  name: string;
  /** Model id that refer to a dbt model */
  modelId: number;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const dbtCloudSchema: Schema<DbtCloud> = s.object<DbtCloud>(
  {
    dbtUniqueId: s.string(),
    compiledSql: s.string(),
    rawSql: s.string(),
    name: s.string(),
    modelId: s.float64(),
  },
  { additionalProperties: s.json() },
);
